namespace ShortsGenerator.Domain;

// Controlled vocabulary for VideoPlan.MusicMood, one per loop in assets/music/<mood>.wav
// (generated by tools/audio/generate_audio_assets.py). Kept as strings rather than an
// enum because MusicMood has been a free-form string on the plan since Day 5 - this pins
// the allowed values without changing the plan's JSON shape.
public static class MusicMood
{
    public const string Upbeat = "upbeat";
    public const string Calm = "calm";

    public static IReadOnlyList<string> All { get; } = [Upbeat, Calm];

    public static string Normalize(string? mood) =>
        All.FirstOrDefault(known => string.Equals(known, mood?.Trim(), StringComparison.OrdinalIgnoreCase)) ?? Upbeat;
}
